const credentials = $input.first().json;
const body = $('Webhook').first().json.body || {};
if (!credentials.success) throw new Error('Credential lookup failed: ' + (credentials.error || 'unknown error'));
const pageId = credentials.platform_metadata?.page_id;
if (!pageId) throw new Error('page_id missing from platform_metadata - reconnect this brand under Settings > Platform Setup');
// Publishing to a Page needs a PAGE token. Brands connected through the OAuth
// wizard store one directly; brands set up by hand only have the user token,
// which the next node exchanges for a page token.
const storedToken = (credentials.platform_metadata?.page_access_token || credentials.access_token || '').trim();
if (!storedToken) throw new Error('No Facebook access token stored for this brand');
const caption = (body.caption || '').trim();
if (!caption) throw new Error('caption is required');
const rawUrls = Array.isArray(body.media_urls) && body.media_urls.length
  ? body.media_urls
  : (body.image_url ? [body.image_url] : []);
const mediaUrls = rawUrls.filter(u => typeof u === 'string' && u.trim()).slice(0, 10);
// Unlike Instagram, Facebook is happy to post text with no media at all.
const postKind = mediaUrls.length > 1 ? 'multi_photo' : (mediaUrls.length === 1 ? 'photo' : 'text');
return [{ json: {
  page_id: pageId,
  stored_token: storedToken,
  branch_id: body.branch_id,
  caption: caption,
  media_urls: mediaUrls,
  image_url: mediaUrls[0] || null,
  post_kind: postKind,
  scheduled_for: body.scheduled_for || null
} }];

const src = $('Extract & Normalize Request').first().json;
const res = $input.first().json || {};
const status = Number(res.statusCode || res.status || 0);
let parsed = res.body;
if (typeof parsed === 'string') { try { parsed = JSON.parse(parsed); } catch (e) { parsed = null; } }
const exchanged = parsed && typeof parsed.access_token === 'string' ? parsed.access_token.trim() : '';
const token = exchanged || src.stored_token;
if (!token) throw new Error('Could not resolve a Facebook Page access token');
// Never log the token itself - only which path produced it.
console.log('[B4] page token resolved via ' + (exchanged ? 'exchange' : 'stored') + ' (HTTP ' + status + ')');
return [{ json: { ...src, access_token: token, token_source: exchanged ? 'exchanged' : 'stored' } }];

const src = $('Choose Page Token').first().json;
// One item per photo so the upload node fans out.
return src.media_urls.map((url, index) => ({ json: { ...src, photo_url: url, photo_index: index } }));

const items = $input.all();
const src = $('Choose Page Token').first().json;
const ids = items.map(i => (i.json || {}).id).filter(Boolean);
// Refuse to publish a partial gallery - better to fail loudly than post half of it.
if (ids.length !== src.media_urls.length) {
  throw new Error('Only ' + ids.length + ' of ' + src.media_urls.length + ' photos uploaded - not publishing a partial post');
}
return [{ json: { ...src, attached_media: JSON.stringify(ids.map(id => ({ media_fbid: id }))) } }];

const src = $('Choose Page Token').first().json;
const res = $input.first().json || {};
// /feed returns { id: '<page>_<post>' }; /photos returns { id: <photo>, post_id: '<page>_<post>' }.
// post_id is what resolves to a real permalink, so prefer it.
const postId = res.post_id || res.id || null;
if (!postId) throw new Error('Facebook accepted the request but returned no post id');
return [{ json: {
  post_id: postId,
  photo_id: res.id || null,
  page_id: src.page_id,
  branch_id: src.branch_id,
  caption: src.caption,
  image_url: src.image_url,
  media_count: src.media_urls.length,
  post_kind: src.post_kind
} }];

const item = $input.item.json || {};
const err = item.error || item;
let message =
  (err && err.error && err.error.message) ||
  (err && err.message) ||
  (typeof err === 'string' ? err : null) ||
  item.reason || null;
if (!message) { try { message = JSON.stringify(err).slice(0, 400); } catch (e) { message = 'Unknown publish error'; } }
const code = (err && err.error && (err.error.code || err.error.error_subcode)) || null;
return { json: { success: false, error: String(message).slice(0, 500), code: code } };
